import React from 'react';

export default function Hero() {
  return (
    <div style={{
      backgroundColor: '#ffffff',
      padding: '80px 20px',
      textAlign: 'center',
    }}>
      <h1 style={{ fontSize: '48px', color: '#2e7d32', marginBottom: '20px', fontWeight: '800' }}>
        AuraPen Saku Education Institute
      </h1>
      <p style={{ fontSize: '18px', marginBottom: '40px', color: '#555555', maxWidth: '600px', marginLeft: 'auto', marginRight: 'auto', lineHeight: '1.6' }}>
        Welcome to AuraPen Saku Education Institute. Shaping the future through digital learning. Explore our courses and start your journey today.
      </p>
      <div>
        <button style={{
          padding: '14px 30px', fontSize: '16px', fontWeight: 'bold', color: '#ffffff', backgroundColor: '#2e7d32',
          border: 'none', borderRadius: '30px', cursor: 'pointer', marginRight: '15px'
        }}>
          Explore Courses
        </button>
        <button style={{
          padding: '14px 30px', fontSize: '16px', fontWeight: 'bold', color: '#2e7d32', backgroundColor: 'transparent',
          border: '2px solid #2e7d32', borderRadius: '30px', cursor: 'pointer'
        }}>
          Contact Us
        </button>
      </div>
    </div>
  );
}
